var m = 2.0;
var E = p.energy;
function Uf(x) { return 4*x*x - x*x*x*x; }
function Ff(x) { return -(8*x - 4*x*x*x); }

var dt = 0.002;
var v0 = Math.sqrt(2*E/m);
var xs = 0, vs = v0, crossings = 0, T = 0, i, xp;
for (i = 0; i < 8000; i++) {
  xp = xs;
  vs = vs + Ff(xs)/m*dt;
  xs = xs + vs*dt;
  T = T + dt;
  if (xp > 0 && xs <= 0) crossings = crossings + 1;
  if (xp < 0 && xs >= 0) crossings = crossings + 1;
  if (crossings >= 2) break;
  if (Math.abs(xs) > 2.35) break;
}
var tm = t - T*Math.floor(t/T);
var x = 0, v = v0;
var n = Math.floor(tm/dt);
for (i = 0; i < n; i++) { v = v + Ff(x)/m*dt; x = x + v*dt; }

var xmin = -2.35, xmax = 2.35, Umin = -6, Umax = 7;
var L = W*0.10, R = W*0.04, Tp = H*0.10, B = H*0.86;
function PX(q) { return L + (q - xmin)/(xmax - xmin)*(W - L - R); }
function PY(q) { return B - (q - Umin)/(Umax - Umin)*(B - Tp); }

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// axes
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(L, PY(0)); ctx.lineTo(W - R, PY(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(PX(0), Tp); ctx.lineTo(PX(0), B); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("x (m)", W - R - 34, PY(0) + 14);
ctx.fillText("U (J)", PX(0) + 6, Tp + 4);

// U(x)
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= 200; i++) {
  var xq = xmin + (xmax - xmin)*i/200;
  var yq = Uf(xq);
  if (yq < Umin) yq = Umin;
  if (yq > Umax) yq = Umax;
  if (i === 0) ctx.moveTo(PX(xq), PY(yq)); else ctx.lineTo(PX(xq), PY(yq));
}
ctx.stroke();

// energy line
ctx.strokeStyle = C.accent;
ctx.setLineDash([5, 4]);
ctx.beginPath(); ctx.moveTo(L, PY(E)); ctx.lineTo(W - R, PY(E)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.fillText("E = " + E.toFixed(1) + " J", L + 4, PY(E) - 6);

// barrier top
ctx.fillStyle = C.faint;
ctx.fillText("barrier top U = 4.0 J", PX(1.41) + 6, PY(4) - 6);

// turning points
if (E < 4) {
  var xt = Math.sqrt(2 - Math.sqrt(4 - E));
  ctx.strokeStyle = C.rule;
  ctx.setLineDash([2, 4]);
  ctx.beginPath(); ctx.moveTo(PX(xt), PY(E)); ctx.lineTo(PX(xt), PY(0)); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(PX(-xt), PY(E)); ctx.lineTo(PX(-xt), PY(0)); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.ink;
  ctx.fillText("turning point", PX(xt) + 5, PY(0) + 26);
}

// particle riding the curve
var px = PX(x), py = PY(Uf(x));
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(px, py, 6, 0, Math.PI*2); ctx.fill();

// kinetic energy bar from curve up to E
if (Uf(x) < E) {
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, PY(E)); ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText("K", px + 7, (py + PY(E))/2 + 4);
}

var K = E - Uf(x);
if (K < 0) K = 0;
out.note = "U = " + Uf(x).toFixed(2) + " J, K = " + K.toFixed(2) + " J, speed = " + Math.sqrt(2*K/m).toFixed(2) + " m/s" + (E >= 4 ? "  (E is above the 4.0 J barrier: the particle escapes)" : "");

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

var floorY = H*0.82, shelfY = H*0.22;
var ax = W*0.16, bx = W*0.62;

// ground
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(W*0.05, floorY); ctx.lineTo(W*0.95, floorY); ctx.stroke();

// shelf
ctx.fillStyle = C.faint;
ctx.fillRect(W*0.50, shelfY, W*0.30, 5);
ctx.fillStyle = C.ink;
ctx.fillText("shelf", W*0.50, shelfY - 8);

// height marker
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(W*0.90, floorY); ctx.lineTo(W*0.90, shelfY); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("h", W*0.905, (floorY + shelfY)/2);

// path 1: straight up then across
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(ax, floorY);
ctx.lineTo(ax, shelfY - 26);
ctx.lineTo(bx, shelfY - 26);
ctx.lineTo(bx, shelfY - 4);
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("path 1", ax + 6, shelfY - 34);

// path 2: wandering
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.moveTo(ax, floorY);
var i, s, qx, qy;
for (i = 1; i <= 60; i++) {
  s = i/60;
  qx = ax + (bx - ax)*s;
  qy = floorY - (floorY - shelfY + 4)*s + Math.sin(s*3.3*Math.PI)*H*0.11*(1 - s*0.4);
  ctx.lineTo(qx, qy);
}
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("path 2", W*0.30, floorY - 12);

// book
ctx.fillStyle = C.figure;
ctx.fillRect(bx - 13, shelfY - 20, 26, 18);
ctx.fillStyle = C.ink;
ctx.fillText("book, mass m", bx + 18, shelfY - 8);

// start marker
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(ax, floorY, 4, 0, Math.PI*2); ctx.fill();
ctx.fillText("start", ax - 12, floorY + 16);

// verdict
ctx.fillStyle = C.ink;
ctx.fillText("gravity does -mgh along either path, so U = mgh is a function of height alone", W*0.06, H*0.96);

out.note = "Change of gravitational potential energy depends only on the change in height.";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var k = p.k, x = p.stretch;
var F = k*x, U = 0.5*k*x*x;

// --- spring picture (top third) ---
var midY = H*0.20, wallX = W*0.08;
var natural = W*0.28;
var pixPerM = W*0.36;
var endX = wallX + natural + x*pixPerM;

ctx.fillStyle = C.faint;
ctx.fillRect(wallX - 7, midY - 26, 7, 52);

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(wallX, midY);
var i;
for (i = 1; i <= 14; i++) {
  var sx = wallX + (endX - 14 - wallX)*i/14;
  var sy = midY + (i % 2 === 0 ? -9 : 9)*(i === 14 ? 0 : 1);
  ctx.lineTo(sx, sy);
}
ctx.lineTo(endX - 14, midY);
ctx.stroke();

ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(wallX + natural, midY - 30); ctx.lineTo(wallX + natural, midY + 30); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("natural length", wallX + natural - 40, midY - 34);

ctx.fillStyle = C.figure;
ctx.fillRect(endX - 14, midY - 14, 28, 28);
ctx.fillStyle = C.ink;
ctx.fillText("stretch x = " + x.toFixed(2) + " m", endX + 22, midY + 4);

// --- F against x graph (bottom) ---
var L = W*0.12, R = W*0.06, Tp = H*0.42, B = H*0.88;
var xmaxG = 0.60, FmaxG = 260;
function GX(q) { return L + q/xmaxG*(W - L - R); }
function GY(q) { return B - q/FmaxG*(B - Tp); }

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(L, B); ctx.lineTo(W - R, B); ctx.stroke();
ctx.beginPath(); ctx.moveTo(L, B); ctx.lineTo(L, Tp); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("x (m)", W - R - 34, B + 15);
ctx.fillText("F = kx  (N)", L + 6, Tp + 2);

// shaded triangle = stored energy
var xg = Math.min(x, xmaxG);
var Fg = Math.min(k*xg, FmaxG);
ctx.fillStyle = C.accent;
ctx.globalAlpha = 0.25;
ctx.beginPath();
ctx.moveTo(GX(0), GY(0));
ctx.lineTo(GX(xg), GY(0));
ctx.lineTo(GX(xg), GY(Fg));
ctx.closePath();
ctx.fill();
ctx.globalAlpha = 1;

// the line F = kx
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
var xEnd = Math.min(xmaxG, FmaxG/k);
ctx.beginPath();
ctx.moveTo(GX(0), GY(0));
ctx.lineTo(GX(xEnd), GY(k*xEnd));
ctx.stroke();

ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(GX(xg), GY(0)); ctx.lineTo(GX(xg), GY(Fg)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.ink;
ctx.fillText("area = stored energy = one half k x squared", GX(0) + 12, GY(0) - (B - Tp)*0.12);
ctx.fillText("F = " + F.toFixed(0) + " N", GX(xg) + 6, GY(Fg) - 6);

out.note = "k = " + k.toFixed(0) + " N/m, x = " + x.toFixed(2) + " m: force " + F.toFixed(1) + " N, stored energy " + U.toFixed(2) + " J";
